{"type":"begin","data":{"path":{"text":"www.nationalbook.org/2022 National Book Awards Longlist for Translated Literature.txt"}}}
{"type":"match","data":{"path":{"text":"www.nationalbook.org/2022 National Book Awards Longlist for Translated Literature.txt"},"lines":{"text":"The ten titles on this year's Translated Literature Longlist were originally written in nine different languages: Arabic, Danish, French, German, Japanese, Norwegian, Persian, Polish, and Spanish. Six honorees have previously been recognized by the National Book Awards. Martin Aitken was a Finalist for Translated Literature in 2018, Jennifer Croft was a Finalist for Translated Literature in 2018, Scholastique Mukasonga was a Finalist for Translated Literature in 2019, Yoko Tawada and Margaret Mitsutani were the Winners of the National Book Award for Translated Literature in 2018, and Olga Tokarczuk was a Finalist for Translated Literature in 2018 and Longlisted in 2019. The authors and translators on the list have been recognized by numerous international prizes, including the Akutagawa Prize, the Prix de la Littérature Arabe, the International Booker Prize, and the PEN Translation Prize. Their work has appeared in a variety of publications, including Granta, Latin American Literature Today, Los Angeles Review of Books, The New Yorker, the New York Times, The Paris Review, and Translation Review, among others.\n"},"line_number":9,"absolute_offset":331,"submatches":[{"match":{"text":"International Booker Prize"},"start":844,"end":870}]}}
{"type":"end","data":{"path":{"text":"www.nationalbook.org/2022 National Book Awards Longlist for Translated Literature.txt"},"binary_offset":null,"stats":{"elapsed":{"secs":0,"nanos":55803,"human":"0.000056s"},"searches":1,"searches_with_match":1,"bytes_searched":7106,"bytes_printed":1533,"matched_lines":1,"matches":1}}}
