{"type":"match","data":{"path":{"text":"literaturecurry.com/GEETANJALI SHREE IS FIRST INDIAN TO WIN INTERNATIONAL BOOKER PRIZE.txt"},"lines":{"text":"The International Booker Prize is awarded every year for a book that is translated into English and published in the UK or Ireland.\n"},"line_number":27,"absolute_offset":1499,"submatches":[{"match":{"text":"International Booker Prize"},"start":4,"end":30}]}}
