{"type":"begin","data":{"path":{"text":"www.oxbelly.com/ADVISORS.txt"}}}
{"type":"match","data":{"path":{"text":"www.oxbelly.com/ADVISORS.txt"},"lines":{"text":"Fiammetta Rocco is a London-based writer and critic. For 25 years she was an editor at The Economist, specialising in books and culture. Her writing has won awards on both sides of the Atlantic. Fiammetta has been the judge of numerous prizes for fiction and non-fiction, and is the administrator of the International Booker Prize. Of Franco-Italian origin, she grew up in Kenya and read Arabic at Oxford University. Her book, The Miraculous Fever Tree, about malaria and the discovery of quinine, was published in Britain and in America. She and her family live between London and Scotland.\n"},"line_number":55,"absolute_offset":7789,"submatches":[{"match":{"text":"International Booker Prize"},"start":304,"end":330}]}}
{"type":"match","data":{"path":{"text":"www.oxbelly.com/ADVISORS.txt"},"lines":{"text":"Fiammetta Rocco is a senior editor and the culture correspondent at The Economist. Her journalism has won awards on both sides of the Atlantic. Fiammetta has been the judge of numerous prizes for fiction and non-fiction, and is also the administrator of the International Booker Prize. Of Franco-Italian origin, she grew up in Kenya and read Arabic at Oxford University. Her book, \"The Miraculous Fever Tree\", about malaria and the discovery of quinine, was published in Britain and in America. She and her family live between London and Scotland.\n"},"line_number":109,"absolute_offset":15865,"submatches":[{"match":{"text":"International Booker Prize"},"start":258,"end":284}]}}
{"type":"end","data":{"path":{"text":"www.oxbelly.com/ADVISORS.txt"},"binary_offset":null,"stats":{"elapsed":{"secs":0,"nanos":60676,"human":"0.000061s"},"searches":1,"searches_with_match":1,"bytes_searched":17364,"bytes_printed":1655,"matched_lines":2,"matches":2}}}
